    const p = fb.pixels;
    const i = (y * fb.width + x) * 4;
    // Straight-alpha "over": correct on opaque 2D backgrounds and on the
    // transparent overlay that 3D carts clear with cls3D().
    const sa = a / 65535;
    const da = p[i + 3] / 65535;
    const oa = sa + da * (1 - sa);
    if (oa <= 0) return;
    const k = (da * (1 - sa)) / oa;
    const s = sa / oa;
    p[i] = r * s + p[i] * k;
    p[i + 1] = g * s + p[i + 1] * k;
