      _blendLine(x1, y1 - s, x2, y2 - s, r, g, b, a);
      _blendLine(x1, y1 + s, x2, y2 + s, r, g, b, a);
      _blendLine(x1 - s, y1, x2 - s, y2, r, g, b, a);
      _blendLine(x1 + s, y1, x2 + s, y2, r, g, b, a);
